    const matches: SearchMatch[] = [];

    if (scope === 'all' || scope === 'runtime') {
      for (const task of runtimeState.tasks) {
        const text = `${task.id} ${task.title} ${task.status} retry ${task.retryCount} ${task.commitId ?? ''} ${task.summary ?? ''} ${task.details ?? ''}`;
