}

export function getArchiMateElementDocumentationGuidance(type?: string): string {
  const normalized = normalizeElementType(type);
  return (
    ELEMENT_DOCUMENTATION_GUIDANCE[normalized as SupportedElementType] ??
    `Describe the element explicitly as a ${humanizeElementType(normalized)} and explain its architectural responsibility, scope, and role in this solution.`
  );
}

export function getArchiMateRelationshipDocumentationGuidance(type?: string): string {
  const normalized = normalizeRelationshipType(type);
  return (
    RELATIONSHIP_DOCUMENTATION_GUIDANCE[normalized as SupportedRelationshipType] ??
    `Describe the relationship explicitly as a ${humanizeElementType(normalized)} and explain why the source and target are connected by this ArchiMate relation in this architecture.`
  );
}

function splitCamelCaseWords(value: string): string {
  return value.replace(/([a-z0-9])([A-Z])/g, '$1 $2');
}

function extractDocumentationTokens(value: string): string[] {
  const normalized = splitCamelCaseWords(value).toLowerCase();
  const matches = normalized.match(/[\p{L}\p{N}][\p{L}\p{N}-]*/gu) ?? [];
  return matches
    .map((token) => token.replace(/^-+|-+$/g, ''))
    .filter((token) => token.length >= 2 || /[^\u0000-\u007f]/.test(token));
}

function createMeaningfulTokenSet(...values: Array<string | undefined>): Set<string> {
  const tokens = values
    .flatMap((value) => extractDocumentationTokens(value ?? ''))
    .filter((token) => !DOCUMENTATION_STOP_WORDS.has(token));
  return new Set(tokens);
}

function countSentenceLikeSegments(value: string): number {
  return value
    .split(/[.!?。！？]+/)
    .map((segment) => segment.trim())
    .filter((segment) => segment.length > 0).length;
}

function hasEnoughDocumentationSignal(documentation: string, guidance: string, title: string, type: string): boolean {
  const titleTokens = createMeaningfulTokenSet(title);
  const guidanceTokens = createMeaningfulTokenSet(guidance, humanizeElementType(type));
  const documentationTokens = extractDocumentationTokens(documentation).filter(
    (token) => !DOCUMENTATION_STOP_WORDS.has(token) && !titleTokens.has(token)
  );
  const uniqueDocumentationTokens = new Set(documentationTokens);
  const guidanceOverlapCount = [...uniqueDocumentationTokens].filter((token) => guidanceTokens.has(token)).length;
  const roleSignalCount = [...uniqueDocumentationTokens].filter((token) => ARCHITECTURE_ROLE_TOKENS.has(token)).length;
  const sentenceCount = countSentenceLikeSegments(documentation);

  return guidanceOverlapCount >= 1 && (roleSignalCount >= 1 || uniqueDocumentationTokens.size >= 5 || sentenceCount >= 2);
}

function getArchitectManagedDocumentationIssue(
  conceptKind: 'element' | 'relationship',
  type: string,
  title: string,
  documentation: string | undefined
): string | undefined {
  const normalizedDocumentation = documentation?.trim() ?? '';
  const guidance =
    conceptKind === 'element'
      ? getArchiMateElementDocumentationGuidance(type)
      : getArchiMateRelationshipDocumentationGuidance(type);

  if (!normalizedDocumentation) {
    return `documentation is required for system-architect managed ${conceptKind}s. ${guidance}`;
  }

  const normalizedTitle = title.trim().toLowerCase();
  if (normalizedTitle && normalizedDocumentation.toLowerCase() === normalizedTitle) {
    return `documentation cannot just repeat the title. ${guidance}`;
  }

  if (hasEnoughDocumentationSignal(normalizedDocumentation, guidance, title, type)) {
    return undefined;
  }

  if (conceptKind === 'element') {
    return `documentation should explain the ArchiMate meaning of ${type} and the element's responsibility or role in this architecture instead of using generic filler. ${guidance}`;
  }

  return `documentation should explain the ArchiMate meaning of ${type} and why the source and target are connected in this architecture instead of using generic filler. ${guidance}`;
}

export function getArchitectManagedElementDocumentationIssue(
  type: string,
  title: string,
  documentation: string | undefined
): string | undefined {
  return getArchitectManagedDocumentationIssue('element', type, title, documentation);
}

export function getArchitectManagedRelationshipDocumentationIssue(
  type: string,
  title: string,
  documentation: string | undefined
): string | undefined {
  return getArchitectManagedDocumentationIssue('relationship', type, title, documentation);
}

function normalizeDocumentationSentence(value: string): string {
  return value.trim().replace(/[.!?]+$/g, '');
}

function buildBaselineDocumentation(guidance: string, context: string, detail?: string): string {
  const parts = [guidance, context, detail]
    .map((value) => value?.trim())
    .filter((value): value is string => Boolean(value && value.length > 0))
    .map((value) => `${normalizeDocumentationSentence(value)}.`);
  return parts.join(' ');
}

function createBaselineElementDocumentation(type: string, context: string, detail?: string): string {
  return buildBaselineDocumentation(getArchiMateElementDocumentationGuidance(type), context, detail);
}

function createBaselineRelationshipDocumentation(type: string, context: string, detail?: string): string {
  return buildBaselineDocumentation(getArchiMateRelationshipDocumentationGuidance(type), context, detail);
}

function isArchitectManaged(extensions?: Record<string, unknown>): boolean {
  const ai4pb = (extensions?.ai4pb ?? {}) as Record<string, unknown>;
  return ai4pb.managedBy === 'system-architect';
}

function needsDocumentationRepair(
  conceptKind: 'element' | 'relationship',
  type: string,
  title: string | undefined,
  documentation: string | undefined
): boolean {
  const normalizedTitle = title?.trim() ?? '';

  if (conceptKind === 'element') {
    return Boolean(getArchitectManagedElementDocumentationIssue(type, normalizedTitle, documentation));
  }

  return Boolean(getArchitectManagedRelationshipDocumentationIssue(type, normalizedTitle, documentation));
}

function repairSystemArchitectManagedDocumentation(graph: SharedKnowledgeGraph): void {
  const elements = graph.elements?.element ?? [];
  const relationships = graph.relationships?.relationship ?? [];

  for (const element of elements) {
    element.type = normalizeElementType(element.type);

    if (!isArchitectManaged(element.extensions)) {
      continue;
    }

    const title = getFirstLangStringValue(element.name) ?? element.identifier;
    const existingDocumentation = getFirstLangStringValue(element.documentation);

    if (!needsDocumentationRepair('element', element.type, title, existingDocumentation)) {
      continue;
    }

    const detail = existingDocumentation && existingDocumentation.toLowerCase() !== title.toLowerCase() ? existingDocumentation : undefined;
    element.documentation = toDocumentation(
      createBaselineElementDocumentation(
        element.type,
        `In this architecture, ${title} defines, constrains, or supports traceable solution intent within the managed model`,
        detail
      )
    );
  }

  for (const relationship of relationships) {
    relationship.type = normalizeRelationshipType(relationship.type);

    if (!isArchitectManaged(relationship.extensions)) {
      continue;
    }

    const title = getFirstLangStringValue(relationship.name) ?? relationship.identifier;
    const existingDocumentation = getFirstLangStringValue(relationship.documentation);

    if (!needsDocumentationRepair('relationship', relationship.type, title, existingDocumentation)) {
      continue;
    }

    const sourceName = getFirstLangStringValue(findElement(graph, relationship.source)?.name) ?? relationship.source;
    const targetName = getFirstLangStringValue(findElement(graph, relationship.target)?.name) ?? relationship.target;
    const detail = existingDocumentation && existingDocumentation.toLowerCase() !== title.toLowerCase() ? existingDocumentation : undefined;

    relationship.documentation = toDocumentation(
      createBaselineRelationshipDocumentation(
        relationship.type,
        `In this architecture, ${sourceName} connects to ${targetName} through a traceable ${relationship.type} relation`,
        detail
      )
    );
  }
}

export function createDefaultSharedKnowledgeGraph(): SharedKnowledgeGraph {
  return {
    identifier: 'ai4pb-shared-knowledge-graph',
    version: '1.0.0',
    name: toLangString('AI4PB Shared Knowledge Graph'),
    documentation: toDocumentation('Schema-compliant shared knowledge graph maintained by OpenCode tools.'),
    metadata: {
      schema: './.opencode/schema/archimate3.1/archimate3.1-exchange-model.schema.json',
      schemaversion: '3.1',
    },
    extensions: {
      ai4pb: {
        managedBy: 'opencode',
        counters: {},
        designSummary: '',
        designDecisions: [],
        runtime: {},
      },
    },
  };
}

export function loadCanonicalKnowledgeGraph(worktree: string): SharedKnowledgeGraph {
  const graphPath = getCanonicalKnowledgeGraphPath(worktree);
  if (!fs.existsSync(graphPath)) {
    const graph = createDefaultSharedKnowledgeGraph();
    saveCanonicalKnowledgeGraph(worktree, graph);
    return graph;
  }
  const raw = fs.readFileSync(graphPath, 'utf8').trim();
  if (!raw) {
    const graph = createDefaultSharedKnowledgeGraph();
    saveCanonicalKnowledgeGraph(worktree, graph);
    return graph;
  }
  return JSON.parse(raw) as SharedKnowledgeGraph;
}

export function saveCanonicalKnowledgeGraph(worktree: string, graph: SharedKnowledgeGraph): void {
  const graphPath = getCanonicalKnowledgeGraphPath(worktree);
  fs.mkdirSync(path.dirname(graphPath), { recursive: true });
  cleanupEmptySections(graph);
  repairSystemArchitectManagedDocumentation(graph);
  validateCanonicalKnowledgeGraph(graph);
  fs.writeFileSync(graphPath, JSON.stringify(graph, null, 2), 'utf8');
}

export function loadLegacyKnowledgeGraph(worktree: string): unknown {
  const graphPath = getLegacyKnowledgeGraphPath(worktree);
  if (!fs.existsSync(graphPath)) {
    return null;
  }
  const raw = fs.readFileSync(graphPath, 'utf8').trim();
  return raw ? JSON.parse(raw) : null;
}

export function nextGraphIdentifier(graph: SharedKnowledgeGraph, prefix: string): string {
  const counters = ensureCounters(graph);
  const current = counters[prefix] ?? 0;
  const next = current + 1;
  counters[prefix] = next;
  return `${prefix}-${String(next).padStart(3, '0')}`;
}

