import * as fs from 'node:fs';
import * as path from 'node:path';

export type RuntimeTaskStatus = 'todo' | 'in_progress' | 'done' | 'blocked';
export type ValidationStatus = 'passed' | 'failed' | 'not_run';
export type RuntimeTaskKind = 'planning' | 'implementation';

export type RuntimeTask = {
  id: string;
  title: string;
  status: RuntimeTaskStatus;
  retryCount: number;
  kind?: RuntimeTaskKind;
  owner?: string;
  summary?: string;
  details?: string;
  commitId?: string;
  softwareUnitId?: string;
  softwareUnitTitle?: string;
  architectureElementId?: string;
  createdAt: string;
  updatedAt: string;
};

export type RuntimeValidation = {
  status: ValidationStatus;
  summary: string;
  updatedAt: string;
  details?: string;
  commitId?: string;
};

export type RuntimeIssue = {
  id: string;
  category: string;
  summary: string;
  details?: string;
  createdAt: string;
};

export type RuntimeState = {
  version: number;
  activeGoal: string;
  designSummary: string;
  designDecisions: string[];
  tasks: RuntimeTask[];
  issues: RuntimeIssue[];
  validations: {
    qa: RuntimeValidation;
    audit: RuntimeValidation;
  };
  release: {
    status: 'not_started' | 'completed';
    summary: string;
    releaseLogPath?: string;
    updatedAt: string;
  };
  counters: {
    task: number;
    issue: number;
  };
  updatedAt: string;
};

function normalizeRetryCount(value: unknown): number {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return Math.max(0, Math.trunc(value));
  }

  if (typeof value === 'string') {
    const parsed = Number.parseInt(value, 10);
    if (Number.isFinite(parsed)) {
      return Math.max(0, parsed);
    }
  }

  return 0;
}

function normalizeRuntimeTask(task: RuntimeTask | Record<string, unknown>): RuntimeTask {
  const record = task as RuntimeTask & { retry_count?: number | string };

  return {
    ...record,
    retryCount: normalizeRetryCount(record.retryCount ?? record.retry_count),
  };
}

function normalizeRuntimeState(state: RuntimeState): { state: RuntimeState; changed: boolean } {
  let changed = state.version !== 2;
  const normalizedTasks = state.tasks.map((task) => {
    const normalizedTask = normalizeRuntimeTask(task);
    if (normalizedTask.retryCount !== task.retryCount) {
      changed = true;
    }
    return normalizedTask;
  });

  return {
    changed,
    state: {
      ...state,
      version: 2,
      tasks: normalizedTasks,
    },
  };
}

const RUNTIME_DIR = path.join('.opencode', 'runtime');
const RUNTIME_FILE = path.join(RUNTIME_DIR, 'project-state.json');
const GRAPH_UPDATE_LOG = path.join('.opencode', 'temp', 'opencode-graph-updates.jsonl');
const KG_FILE = path.join('.opencode', 'temp', 'SystemArchitecture.json');

export function getRuntimeFilePath(worktree: string): string {
  return path.join(worktree, RUNTIME_FILE);
